export const PAPERS: PaperInput[] = [
  {"id":"2610.05608","title":"Kandinsky 6.0 Video: Foundation Models for Synchronized Video and Audio Generation","up":94,"href":"https://arxiv.org/abs/2610.05608","abstract":"We present Kandinsky 6.0 Video, a family of foundation diffusion models for synchronized text-to-audio-video generation, comprising Kandinsky 6.0 Video Lite (3B parameters) and Kandinsky 6.0 Video Pro (29B parameters). Both models generate 5-second video clips with synchronized 44 kHz audio, including lip-sync, in text-to-audio-video (T2AV) and image-to-audio-video (I2AV) modes; a built-in super-resolution model raises the output resolution to Full-HD (1920$\\times$1080). Building on the video generation capabilities of Kandinsky 5.0, Kandinsky 6.0 Video employs a dual-stream CrossDiT architect","pdfUrl":"https://arxiv.org/pdf/2610.05608","primaryCategory":"cs.CV","crossrefDoi":"https://doi.org/10.5594/smpte.st2064-1.2015"},
  {"id":"2610.02840","title":"PointWAM: 3D World Action Modeling for Dexterous Robotic Manipulation","up":37,"href":"https://arxiv.org/abs/2610.02840","abstract":"World action models jointly learn to forecast world dynamics and predict robot actions, such that the learned internal world dynamics guide accurate actions. Existing approaches typically represent the world as RGB frames or latent counterparts while predicting actions as end-effector poses or joint angles, but they often struggle to capture the 3D spatial structure and contact geometry central to dexterous manipulation. We introduce Point World Action Model (PointWAM), a 3D world action model that decomposes the world into a scene (i.e., environment) and hands (i.e., actor), and jointly forec","pdfUrl":"https://arxiv.org/pdf/2610.02840","primaryCategory":"cs.RO"},
  {"id":"2610.04198","title":"ALoDLM: Adaptively Looped Diffusion Language Models","up":37,"href":"https://arxiv.org/abs/2610.04198","abstract":"Diffusion language models (DLMs) enable fast generation by predicting multiple tokens in parallel, but their practical adoption remains limited by a persistent quality gap relative to comparably sized autoregressive (AR) models. We attribute this gap to a computation-difficulty mismatch: within a partially observed sequence, some unknown tokens are easy to predict, while others require substantially more computation. Existing DLMs nevertheless apply uniform computational depth to all unknown positions at each denoising step. We introduce ALoDLM, which replaces uniform computation with token-ad","pdfUrl":"https://arxiv.org/pdf/2610.04198","primaryCategory":"cs.AI"},
  {"id":"2610.05162","title":"Memadapter: Counterfactual Adaptation Against Memory-induced Sycophancy","up":16,"href":"https://arxiv.org/abs/2610.05162","abstract":"Long-term memory enables LLM-based agents to retain and reuse information across tasks and sessions, supporting personalization and long-horizon interactions. However, persistent memories can also induce sycophancy, causing agents to over-align with users' historical beliefs even when they are inaccurate, outdated, or inconsistent with objective evidence. Existing mitigation methods assume that memory-induced sycophancy originates from biased or incorrect memories and attempt to reduce this risk by filtering such memories at different stages of the memory pipeline. However, in the real world, ","pdfUrl":"https://arxiv.org/pdf/2610.05162","primaryCategory":"cs.AI"},
  {"id":"2609.37267","title":"Foundations of Proactive Agents: Principles, Technical Layers, and Proactivity-Gym","up":12,"href":"https://arxiv.org/abs/2609.37267","abstract":"Proactive LLM agents can turn idle compute into useful support before users ask. Yet even correct work can misread user context, impose review costs, or undermine trust. This work proposes foundations for designing, realizing, and evaluating proactive LLM agents around three joint principles (3T): Task Capability, anticipating relevant needs and correctly performing useful work; Temporal Allocation, allocating compute according to resource availability and when results are needed; and Trust, sustaining users' confidence and appropriate reliance on the agent. We connect these objectives to a de","pdfUrl":"https://arxiv.org/pdf/2609.37267","primaryCategory":"cs.AI"},
  {"id":"2610.00923","title":"CANOPY: Adaptive-Granularity Evidence Compression for Multimodal RAG","up":11,"href":"https://arxiv.org/abs/2610.00923","abstract":"Multimodal RAG retrieves text, tables, images, and videos, but choosing a retrieval granularity does not determine how much context to retain within each item. Coarse units include irrelevant content, while uniformly fine selection can remove context needed to interpret the evidence. Existing compressors address this trade-off with modality-specific mechanisms, leaving open a shared procedure for adapting the retained extent region by region across heterogeneous items. We introduce CANOPY (Canonical Projection over Hierarchy), a framework for adaptive-granularity post-retrieval evidence compre","pdfUrl":"https://arxiv.org/pdf/2610.00923","primaryCategory":"cs.IR"},
  {"id":"2610.05303","title":"ASCENT: Online Test-Time Training of Long-Horizon Agents via Self-Distillation of Verified Experience","up":11,"href":"https://arxiv.org/abs/2610.05303","abstract":"A large language model (LLM) agent solves long-horizon tasks through many reasoning-action turns, with one verification signal at termination. Deployed agents face streams of related tasks, making their trajectories a natural resource for improvement. In-context adaptation agents store reflections, memories, or skills as text, so reuse depends on retrieving the right experience and on a frozen policy executing it. We study Online Agentic Test-Time Training (OaTTT), which trains the LLM's weights on its own execution trajectories during deployment. The agent executes each task once, in one pass","pdfUrl":"https://arxiv.org/pdf/2610.05303","primaryCategory":"cs.LG"},
  {"id":"2609.24890","title":"OSWorld-Pro: Process-based Evaluation for Computer Use Agents","up":10,"href":"https://arxiv.org/abs/2609.24890","abstract":"Evaluation of Computer-Use Agents (CUAs) is often limited to the final deliverables they create (at the end of hundreds of steps) and assessed with functional verifiers, as seen in OSWorld. However, such evaluation of end-state performance lacks transparency into how and why agents fail in various tasks, obfuscating critical insight for subsequent improvement. For instance, agents that err during keyboard inputs would require a different mitigation strategy from those that fail to precisely provide click-based inputs on the graphical UI. We introduce OSWorld-Pro: a set of over 300 tasks contai","pdfUrl":"https://arxiv.org/pdf/2609.24890","primaryCategory":"cs.CL"},
  {"id":"2610.04929","title":"RobotUse: Allocating Computation, Context, and Decisions","up":10,"href":"https://arxiv.org/abs/2610.04929","abstract":"Robot agents must connect their intended actions to observed outcomes while retaining the context needed to revise their choices over repeated attempts. Existing interfaces often leave these choices inside predefined tools or require agents to manage detailed execution code and its growing history. We introduce RobotUse, a robot agent harness that organizes computation, context, and decisions around specifying and revising physical actions. Agents visually select targets and poses, while the backend handles geometry, motion planning, and control. Subagents retain detailed interactions within e","pdfUrl":"https://arxiv.org/pdf/2610.04929","primaryCategory":"cs.RO"},
  {"id":"2609.36099","title":"Data Unlearning via Inverse Distillation","up":8,"href":"https://arxiv.org/abs/2609.36099","abstract":"Multi-step matching models, including flow and diffusion models, produce high-quality outputs but incur substantial inference costs and may reproduce unwanted components of their training datasets. We introduce Inverse Distillation Unlearning (IDU), a unified framework that simultaneously distills a teacher multi-step matching model into an efficient one-step student generator and suppresses outputs corresponding to a designated training subset. We first formulate distillation as a min-max objective over a data distribution and then represent this distribution as a mixture of the forget-set an","pdfUrl":"https://arxiv.org/pdf/2609.36099","primaryCategory":"cs.LG"},
  {"id":"2610.03120","title":"In-Distribution Forcing for Long Video Generation at Test Time","up":8,"href":"https://arxiv.org/abs/2610.03120","abstract":"Modern autoregressive (AR) video diffusion models excel at short-horizon video generation, yet generating long videos remains challenging due to drifting, where colors and textures shift, and motion dynamics decay. Existing works primarily rely on KV conditioning, which selects or modifies cached key-value (KV) entries to mitigate drifting. However, we observe that KV conditioning alone is insufficient as it assumes cached KV entries remain in-distribution. This assumption fails beyond the training horizon: nothing constrains the construction of KV entries during rollout, giving rise to the KV","pdfUrl":"https://arxiv.org/pdf/2610.03120","primaryCategory":"cs.CV"},
  {"id":"2610.04318","title":"Rethinking Long-Video Efficiency: A Joint Allocation Perspective on Frames, Pixels, and Front-End Latency","up":8,"href":"https://arxiv.org/abs/2610.04318","abstract":"Efficient long-video understanding with vision-language models (VLMs) is often framed as selecting informative frames or visual tokens at a fixed native resolution. We show that per-frame resolution can instead be traded for denser temporal coverage, while front-end decoding latency depends on the size of the candidate pool rather than the final token budget. An empirical study across multiple VLMs and long-video benchmarks yields three findings: dense low-resolution sampling outperforms sparse native-resolution sampling at matched token budgets; resolution-sensitive tasks benefit from selecte","pdfUrl":"https://arxiv.org/pdf/2610.04318","primaryCategory":"cs.CV"},
  {"id":"2610.05107","title":"SearchJev: A Fast and Calibrated System-1 Model for Search Agents","up":8,"href":"https://arxiv.org/abs/2610.05107","abstract":"Search agents repeatedly make short decisions about relevance, evidence sufficiency, and search actions. Using generative language models for these decisions introduces latency and unreliable confidence. We present SearchJev, a fast and calibrated System-1 model that separates search decisions from System-2 reasoning and generation. Given a search state and a decision schema, SearchJev directly scores legal options without autoregressive output generation. We propose Soft-Label Learning for Calibrated Decisions (SLCD) to learn decision probabilities from uncertain supervision and calibrate the","pdfUrl":"https://arxiv.org/pdf/2610.05107","primaryCategory":"cs.IR"},
  {"id":"2610.05894","title":"Noise Out, Bias In: Targeted Bias Injection in Diffusion Language Models via Closed-Loop Activation Steering","up":8,"href":"https://arxiv.org/abs/2610.05894","abstract":"Masked diffusion language models (dLLMs) generate text by iteratively denoising masked positions, re-predicting each token multiple times before it is committed. An autoregressive decoder exposes an answer's distribution once, at the step that commits it; a dLLM exposes it at every denoising step before commitment, and we show that an adversary can exploit this. Since an answer remains open to revision over many denoising steps, an adversary with access to internal activations can watch how likely the model is to produce a chosen answer and adjust the intervention accordingly. Building on this","pdfUrl":"https://arxiv.org/pdf/2610.05894","primaryCategory":"cs.CL"},
  {"id":"2610.06617","title":"RealtimeWAM: One-Step Asynchronous World Action Models","up":8,"href":"https://arxiv.org/abs/2610.06617","abstract":"World Action Models (WAMs) incorporate visual representations from video generation backbones to guide action prediction. Recent efficient WAMs adopt Mixture-of-Transformers (MoT) architectures and compute video representations once for reuse by the action expert. However, intra-expert iteration (\\ie, multi-step action denoising) and inter-expert waiting (\\ie, sequential execution of the video and action experts) still limit inference efficiency. To this end, we present RealtimeWAM, an extremely efficient WAM variant with one-step action generation and asynchronous inference, addressing these ","pdfUrl":"https://arxiv.org/pdf/2610.06617","primaryCategory":"cs.CV"},
  {"id":"2610.06833","title":"Towards Looped Models Done Right, Part II: Rethinking at Fixed Points","up":8,"href":"https://arxiv.org/abs/2610.06833","abstract":"Every recurrence of a looped language model adds cost in training, decoding, prefill, and reinforcement learning (RL). The closer recurrent states get to fixed points, the less the path to them matters. This enables truncated backpropagation in training; terminal key-value (KV) sharing for decoding with almost no loss in accuracy; a distilled student that prefills up to 1.79x faster; and RL updates that compute gradients from saved rollout states, 2x faster than backpropagating through the replayed trajectory. We therefore improve the two components of training that shape these fixed points: t","pdfUrl":"https://arxiv.org/pdf/2610.06833","primaryCategory":"cs.LG"},
  {"id":"2610.05719","title":"When to Switch: Reliable Action-Chunk Extension for Vision-Language-Action Models","up":7,"href":"https://arxiv.org/abs/2610.05719","abstract":"Vision-Language-Action (VLA) models serve as unified policies for robotic manipulation, yet their expensive inference forces robots to pause between policy calls, resulting in stop-and-go execution that interrupts smooth motion and prolongs task completion. Extending the action chunk reduces policy calls and hence these pauses, but predicting farther into the future makes long-chunk execution unreliable. To understand where this unreliability arises, we analyze action errors within long chunks and find that they concentrate around transitions between manipulation subskills, growing sharply wit","pdfUrl":"https://arxiv.org/pdf/2610.05719","primaryCategory":"cs.RO"},
  {"id":"2610.05870","title":"Certification of Real Images through Calibrated Content Authentication","up":7,"href":"https://arxiv.org/abs/2610.05870","abstract":"Generative models can synthesize high-quality inauthentic multimedia content that is already being misused at scale. We evaluate twenty deepfake detectors against ten generators released in the last four years and find accuracy decreasing over time, from near-perfect 99.5% to 76%. Adversarial perturbations further reduce every baseline detector to below 2% accuracy, effectively inverting the detector's assigned label. We argue that this unreliability reflects a fundamental ambiguity: generators can reproduce authentic content exactly (e.g., through memorization), so content alone cannot reveal","pdfUrl":"https://arxiv.org/pdf/2610.05870","primaryCategory":"cs.CV"},
  {"id":"2610.06851","title":"Base Models Can Reason By Taking a Cue From Training Data","up":6,"href":"https://arxiv.org/abs/2610.06851","abstract":"In this paper, we study how training data creates associations between the tokens at the start of a base model's response and the reasoning behavior that follows. First, we demonstrate that fixing particular starting token cues makes a base model's performance competitive with that of its reinforcement learning (RL)-trained counterparts on math and coding. For instance, the cue \".\\n\\nOkay\" raises Olmo-3-7B's MATH-500 pass@1 accuracy from 42% to 78%, while \"Alright,\" raises Qwen3-14B's from 72% to 87%. Second, RL makes these cues more likely, while fixing them recovers much of its performance g","pdfUrl":"https://arxiv.org/pdf/2610.06851","primaryCategory":"cs.LG"},
  {"id":"2609.39420","title":"QuantCode Model: Specializing Language Models for Executable Algorithmic Trading Code","up":5,"href":"https://arxiv.org/abs/2609.39420","abstract":"Large language models are strong general-purpose code generators, but executable algorithmic trading remains a demanding specialization target: a model must translate a natural-language strategy specification into correct program logic for a specialized trading framework, execute on historical data, produce trades, and remain semantically faithful to the request. We study two complementary mechanisms for specializing language models for this setting: continued pretraining on algorithmic-trading framework code and supervised fine-tuning (SFT) on agent-validated request-to-code pairs. Evaluation","pdfUrl":"https://arxiv.org/pdf/2609.39420","primaryCategory":"cs.CL"},
  {"id":"2610.06577","title":"Optimizing the Optimizer: Language Models Discover Faster Molecular Relaxation","up":5,"href":"https://arxiv.org/abs/2610.06577","abstract":"Geometry optimization is a major cost in many quantum-chemical workflows: each optimization step requires one force evaluation, and at the density-functional level that evaluation dominates the wall time. Research in this area has produced a broad range of optimization methods, and we ask whether a language model can improve on the best of them through autoresearch. An agent rewrites the optimizer itself to minimize force-call counts, restrained by two admission gates that reject premature stopping and improvements that do not generalize to unseen molecules. Starting from Sella, the fastest op","pdfUrl":"https://arxiv.org/pdf/2610.06577","primaryCategory":"physics.chem-ph"},
  {"id":"2609.39490","title":"OmniReasoning: Pushing the Limits of Audio-Visual Joint Reasoning","up":4,"href":"https://arxiv.org/abs/2609.39490","abstract":"Recent advances have enabled unified omni-modal models in understanding audio, vision, and language. However, existing benchmarks, training data, and learning methods largely treat the modalities independently, leaving the capability of audio-visual joint reasoning poorly evaluated and insufficiently elicited. We address this gap with a benchmark, data engine, and learning method. First, we introduce OmniReasoningBench, a benchmark where both audio and visual evidence are indispensable. It comprises 1,150 multiple-choice and open-ended questions across two tasks, reasoning over video and reaso","pdfUrl":"https://arxiv.org/pdf/2609.39490","primaryCategory":"cs.CV"},
  {"id":"2610.04116","title":"CUAWright: A Minimal Unified Interface for Digital Agents","up":4,"href":"https://arxiv.org/abs/2610.04116","abstract":"The prevailing approach to computer-use agents couples a model with a domain-specific harness: a browser or desktop environment equipped with human engineered tools that are fixed before task execution. As models' coding capabilities improve, the GUI native and static harness prevents them from direct programmatic operation on system state, as well as flexible construction of tools. To this end, we introduce CUAWright, a minimal terminal harness of roughly 3K lines of code that uses bash commands as its sole action interface, and a file system as its evolvable space for dynamically creating to","pdfUrl":"https://arxiv.org/pdf/2610.04116","primaryCategory":"cs.AI"},
  {"id":"2610.05416","title":"Prism: Dynamic Sparse Attention for Native 2K Joint Video-Audio Generation Model Training","up":4,"href":"https://arxiv.org/abs/2610.05416","abstract":"Natively training joint video-audio generation models at higher resolutions empowers them to learn richer visual details and sharper motion dynamics. However, full attention incurs quadratic cost and, as resolution increases, spreads attention over increasingly redundant tokens, diluting learning signals for informative content and disrupting pretrained priors. Existing sparse attention methods either target training-free acceleration or overlook the unique structure of joint video-audio data, where cross-modal interactions are inherently concentrated around sound-producing regions. To address","pdfUrl":"https://arxiv.org/pdf/2610.05416","primaryCategory":"cs.CV"},
];

